<?php
declare(strict_types=1);
require_once __DIR__ . '/_bootstrap.php';
require_once __DIR__ . '/../config/orcamento_module.php';
require_once __DIR__ . '/_print_brand.php';

$pdo=orc_db();
$companyId=orc_company_id();
orc_require_enabled($pdo,$companyId);
orc_require_schema($pdo);
$id=max(0,(int)($_GET['id']??0));
$model=strtolower(trim((string)($_GET['modelo']??'a4')));
if(!in_array($model,['72mm','a4'],true))$model='a4';
if($id<=0){http_response_code(400);die('Orçamento inválido.');}
$q=orc_fetch($pdo,$companyId,$id);
if(!$q){http_response_code(404);die('Orçamento não encontrado.');}
$st=$pdo->prepare('SELECT * FROM orcamento_items WHERE company_id=? AND quote_id=? ORDER BY id');$st->execute([$companyId,$id]);$items=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$st=$pdo->prepare('SELECT * FROM orcamento_payments WHERE company_id=? AND quote_id=? ORDER BY due_date,id');$st->execute([$companyId,$id]);$payments=$st->fetchAll(PDO::FETCH_ASSOC)?:[];
$st=$pdo->prepare('SELECT name,cnpj,cpf,endereco,numero,bairro,cidade,estado,email,whatsapp FROM companies WHERE id=? LIMIT 1');$st->execute([$companyId]);$company=$st->fetch(PDO::FETCH_ASSOC)?:[];
$customer=[];
if((int)($q['person_id']??0)>0){try{$st=$pdo->prepare('SELECT name,document,phone,whatsapp,zip_code,address,number,complement,district,city,state FROM finance_people WHERE company_id=? AND id=? LIMIT 1');$st->execute([$companyId,(int)$q['person_id']]);$customer=$st->fetch(PDO::FETCH_ASSOC)?:[];}catch(Throwable $e){}}
$logo=nexa_print_logo_url($companyId);
function orcp_h($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function orcp_money($v):string{return 'R$ '.number_format((float)$v,2,',','.');}
function orcp_qty($v):string{$n=number_format((float)$v,4,',','.');return rtrim(rtrim($n,'0'),',');}
function orcp_date($v):string{$t=$v?strtotime((string)$v):false;return$t?date('d/m/Y',$t):'';}
function orcp_doc(array $c):string{return trim((string)($c['cnpj']??''))!==''?(string)$c['cnpj']:(string)($c['cpf']??'');}
function orcp_company_address(array $c):string{return trim(implode(' ',array_filter([(string)($c['endereco']??''),(string)($c['numero']??''),(string)($c['bairro']??''),(string)($c['cidade']??''),(string)($c['estado']??'')],fn($v)=>trim($v)!=='')));}
$customerName=trim((string)($q['person_name_snapshot']??''))?:'Cliente não informado';
$customerDoc=trim((string)($q['person_document_snapshot']??''));
$customerPhone=trim((string)($q['person_phone_snapshot']??''));
$customerAddr='';
if($customer){$customerAddr=trim((string)($customer['address']??'').(trim((string)($customer['number']??''))!==''?', '.trim((string)$customer['number']):''));$rest=array_filter([(string)($customer['complement']??''),(string)($customer['district']??''),trim((string)($customer['city']??'').((string)($customer['state']??'')!==''?'/'.(string)$customer['state']:'')),(string)($customer['zip_code']??'')],fn($v)=>trim($v)!=='');if($rest)$customerAddr.=($customerAddr!==''?' - ':'').implode(' - ',$rest);}
$deliveryAddr=trim((string)($q['delivery_address']??'').(trim((string)($q['delivery_number']??''))!==''?', '.trim((string)$q['delivery_number']):''));$deliveryRest=array_filter([(string)($q['delivery_complement']??''),(string)($q['delivery_district']??''),trim((string)($q['delivery_city']??'').((string)($q['delivery_state']??'')!==''?'/'.(string)$q['delivery_state']:'')),(string)($q['delivery_zip_code']??'')],fn($v)=>trim($v)!=='');if($deliveryRest)$deliveryAddr.=($deliveryAddr!==''?' - ':'').implode(' - ',$deliveryRest);
$number=str_pad((string)(int)$q['quote_number'],6,'0',STR_PAD_LEFT);
$status=orc_status_label((string)$q['status']);
$back='orcamento_editar.php?id='.$id;
?>
