<div class="totals"><div><span>Produtos</span><b><?=orcp_h(orcp_money($q['total_products']))?></b></div><div><span>Serviços</span><b><?=orcp_h(orcp_money($q['total_services']))?></b></div><?php if((float)($q['discount_amount']??0)>0):?><div><span>Desconto<?=((float)($q['discount_percent']??0)>0?' ('.number_format((float)$q['discount_percent'],2,',','.').'%)':'')?></span><b>- <?=orcp_h(orcp_money($q['discount_amount']))?></b></div><?php endif;?><?php if((float)($q['addition_amount']??0)>0):?><div><span>Acréscimo<?=((float)($q['addition_percent']??0)>0?' ('.number_format((float)$q['addition_percent'],2,',','.').'%)':'')?></span><b>+ <?=orcp_h(orcp_money($q['addition_amount']))?></b></div><?php endif;?><?php if((float)($q['freight_amount']??0)>0):?><div><span>Frete</span><b>+ <?=orcp_h(orcp_money($q['freight_amount']))?></b></div><?php endif;?><div class="grand"><span>Total</span><span><?=orcp_h(orcp_money($q['total_general']))?></span></div></div>
